# brain/driver.py -- board-agnostic motor + steering control for the RC crawler (Pi 5 + Jetson via
# hal.current() / brain/boards/<board>.py; add board-specific code in the board backends, NOT here).
#
# Throttle (ESC (Electronic Speed Controller)) and steering (servo) PWM are generated by a PCA9685 over I2C, so the
# pulse timing stays rock-solid even while the SBC is busy running the LLM. A forward HC-SR04 (via the board's
# raw-ping backend, brain/hcsr04_pi5.py / hcsr04_jetson.py) refuses forward motion under OBSTACLE_CM.
#
# SAFETY: the old design had a Pico hardware watchdog; that is gone now, so a software
# failsafe takes its place. A background control thread forces the ESC (Electronic Speed Controller) back to NEUTRAL
# when a move's deadline passes, on STOP, on any error, or when an obstacle is detected
# ahead. The ESC (Electronic Speed Controller) is armed at neutral on startup.
#   LIMITATION: if the whole Python process is killed, the PCA9685 holds the last pulse
#   it was given. There is no hardware watchdog to catch that -- keep a PHYSICAL kill
#   switch on the motor battery within reach (see README).
#
# Threading model: ALL PCA9685 (I2C) writes go through self._io. State is guarded by
# self._lock. The control thread is the ONLY place that drives the PWM outputs during
# normal operation; command()/stop() only mutate state, so two threads never issue
# overlapping I2C transactions.
#
# DRY RUN: set ROBOT_DRY_RUN=1 (or ROBOT_SIMULATE=1) to run with NO hardware -- the
# ServoKit/DistanceSensor are swapped for fakes and the real adafruit_servokit/gpiozero
# imports are skipped entirely (so this runs on a laptop or an unwired Pi). Every intended
# PWM/GPIO action is logged to the "robot.hw" logger, so you can watch the model->hardware
# mapping on the console before any motor exists. Live mode logs the same lines, so the
# mapping is auditable there too.

import logging
import os
import threading
import time

VALID_DRIVE = {"FORWARD", "REVERSE", "STOP"}
VALID_STEER = {"LEFT", "CENTER", "RIGHT"}

log = logging.getLogger("robot.hw")


def _envf(key, default):
    try:
        return float(os.environ.get(key, default))
    except (TypeError, ValueError):
        return float(default)


def _envi(key, default):
    try:
        return int(os.environ.get(key, default))
    except (TypeError, ValueError):
        return int(default)


def dry_run_enabled():
    return os.environ.get("ROBOT_DRY_RUN", os.environ.get("ROBOT_SIMULATE", "0")) == "1"


def motors_off_enabled():
    # STATIONARY / tabletop mode: run fully LIVE but suppress the ESC + steering PWM so the wheels
    # never move (the console still logs every intended command, like dry-run). Distinct from dry_run,
    # which ALSO fakes the camera/face/wake word/sounds -- motors-off keeps all of those live and only
    # silences the motor outputs. Has no effect under dry_run (that already fakes the motors).
    return os.environ.get("ROBOT_MOTORS_OFF", "0") == "1"


# ---------------------------------------------------------------------------
# Dry-run fakes. These stand in for adafruit_servokit.ServoKit and
# gpiozero.DistanceSensor so the whole pipeline runs with no I2C/GPIO present.
# They only need to silently accept the same attribute surface the real classes
# expose -- the RobotDriver itself does all the logging (see _write_throttle /
# _write_steer), so the model->hardware mapping reads identically in dry run and
# live. NOTE: a fake distance is reported in METRES, exactly like gpiozero's
# DistanceSensor.distance, because distance_cm() multiplies by 100.
# ---------------------------------------------------------------------------
class _FakeChannel:
    def __init__(self):
        self.throttle = 0.0
        self.angle = 0.0
        self.actuation_range = 180

    def set_pulse_width_range(self, min_us, max_us):
        self._pulse = (min_us, max_us)


class FakeServoKit:
    """Mimics adafruit_servokit.ServoKit's attribute surface; drives nothing."""

    def __init__(self, channels=16):
        self.continuous_servo = [_FakeChannel() for _ in range(channels)]
        self.servo = [_FakeChannel() for _ in range(channels)]


class FakeDistanceSensor:
    """Mimics gpiozero.DistanceSensor; .distance is synthetic and in METRES."""

    def __init__(self, max_distance=4.0, cm=200.0):
        self.max_distance = max_distance
        self._cm = cm

    @property
    def distance(self):
        return min(self._cm / 100.0, self.max_distance)

    def set_cm(self, cm):   # let a REPL/test inject an obstacle live
        self._cm = float(cm)

    def close(self):
        pass


class RobotDriver:
    """Owns all PWM output and the safety control loop. Thread-safe."""

    def __init__(self):
        self.dry_run = dry_run_enabled()
        # Stationary mode only matters when we're otherwise LIVE (dry_run already fakes the motors).
        self.motors_off = motors_off_enabled() and not self.dry_run
        # Distance-sensor backend: 'hcsr04' (default -- 3x ultrasonic on GPIO) | 'vl53l1x' (3x I2C ToF).
        self.sensor_type = (os.environ.get("ROBOT_SENSOR_TYPE", "hcsr04").strip().lower() or "hcsr04")

        # --- PCA9685 channels ---
        self.esc_ch = _envi("ROBOT_ESC_CHANNEL", 0)
        self.steer_ch = _envi("ROBOT_STEER_CHANNEL", 1)
        channels = _envi("ROBOT_PCA9685_CHANNELS", 16)

        # --- Steering geometry (servo degrees). Calibrate so wheels point straight at CENTER. ---
        self.steer_center = _envf("ROBOT_STEER_CENTER", 90.0)
        self.steer_left = _envf("ROBOT_STEER_LEFT", 55.0)
        self.steer_right = _envf("ROBOT_STEER_RIGHT", 125.0)

        # --- Throttle map (dead-band-compensated). A crawler ESC has a LARGE forward dead-band -- it doesn't
        #     start pulling until well above 1500us -- so we map speed 1..100 onto the ESC's *usable* band
        #     (skipping the dead zone), keeping the safe-stop path unchanged. These four are ABSOLUTE SIGNED
        #     throttles (1500us=0.0, 2000us=+1.0, 1000us=-1.0), NOT magnitudes: FORWARD sits ABOVE neutral,
        #     REVERSE BELOW it. MIN_*_SPEED = the slowest end (just crawls), MAX_*_SPEED = the fastest.
        #     Calibrate per ESC on the bench -> the ESC patch (scripts/patches/common/1_esc_*.sh) writes them.
        self.fwd_floor = _envf("ROBOT_MIN_FORWARD_SPEED", 0.60)   # FORWARD slowest crawl (just engages)
        self.fwd_ceil = _envf("ROBOT_MAX_FORWARD_SPEED", 1.00)    # FORWARD fastest (lower = slower top speed)
        # REVERSE is a SIGNED absolute throttle BELOW neutral (like forward is above it), NOT a magnitude.
        # MIN_REVERSE_SPEED = slowest reverse (just below neutral); MAX_REVERSE_SPEED = fastest (deeper below,
        # so numerically LOWER / more-negative than the min). E.g. neutral 0.25: min 0.00 (1500us crawl),
        # max -0.20 (1400us, faster). speed 1..100 maps min..max.
        self.rev_floor = _envf("ROBOT_MIN_REVERSE_SPEED", 0.0)    # REVERSE slowest crawl (just below neutral)
        self.rev_ceil = _envf("ROBOT_MAX_REVERSE_SPEED", -0.60)   # REVERSE fastest (deeper below neutral)
        # Optional throttle QUANTIZATION: round the mapped throttle to multiples of this step (measured from
        # the floor) so speed changes in clean increments instead of continuously. 0 / empty = OFF (smooth).
        self.speed_step = _envf("ROBOT_SPEED_INCREMENT_STEP", 0.0)
        # Legacy single cap: if ROBOT_MAX_THROTTLE is still set < a floor it would re-create the
        # "never moves" bug, so it's NO LONGER applied to the map (kept readable for old configs).
        self._legacy_max = _envf("ROBOT_MAX_THROTTLE", 0.0)
        self.invert = _envi("ROBOT_THROTTLE_INVERT", 0) == 1     # flip if FWD/REV are swapped
        self.arm_secs = _envf("ROBOT_ESC_ARM_SECS", 3.0)
        # --- ESC neutral: the throttle the driver RESTS + STOPS at, and holding it also ARMS the ESC.
        #     Most ESCs use 0.0 (1500us). But some are OFFSET: on one bench ESC 0.0/1500us was a slow
        #     reverse (it crept), and it only truly stopped -- and armed (long "ready" beep, wheels dead
        #     still) -- at 0.25/1625us. Set ROBOT_ESC_NEUTRAL to that value. Forward/reverse floors+ceils
        #     stay ABSOLUTE (an ESC's forward still engages at its own ~1800us wherever we call neutral).
        #     Keep the ESC powered when the brain starts so it sees this and arms. 0.0 = standard. ---
        self.neutral = _envf("ROBOT_ESC_NEUTRAL", 0.0)

        # --- Reverse mode. DEFAULT is F/R "direct reverse": a single -throttle reverses immediately
        #     (this tested reliable on the WP-1060; the F/B/R double-click proved finicky). Set
        #     ROBOT_ESC_REVERSE_DOUBLETAP=1 ONLY for the F/B/R jumper, where the FIRST reverse push
        #     only brakes and reverse engages on the SECOND push after neutral -- the loop then
        #     auto-taps reverse -> neutral -> reverse. F/R has no brake (STOP coasts). ---
        self.rev_doubletap = _envi("ROBOT_ESC_REVERSE_DOUBLETAP", 0) == 1
        self.rev_brake_ms = _envi("ROBOT_ESC_REV_BRAKE_MS", 400)   # (F/B/R only) tap1 the ESC reads as brake
        self.rev_gap_ms = _envi("ROBOT_ESC_REV_GAP_MS", 300)       # (F/B/R only) neutral gap between taps

        # --- Obstacle sensing: forward FORWARD-cut gate + side-awareness (semi-hex 3-sensor array) ---
        self.obstacle_cm = _envf("ROBOT_OBSTACLE_CM", 30.0)            # forward gate (cuts FORWARD)
        self.side_obstacle_cm = _envf("ROBOT_SIDE_OBSTACLE_CM", 25.0)  # explore steering-avoid
        # gpiozero's software-timed echo can jitter ONE garbage frame (even a NEGATIVE cm) under the 20Hz
        # loop's CPU load. Require this many CONSECUTIVE close/failed reads before ABORTING a move, so one
        # spurious frame can't kill a drive. Each frame still holds neutral, so it never drives while unsure.
        self.obstacle_debounce = max(1, _envi("ROBOT_OBSTACLE_DEBOUNCE", 3))
        # Sensor echo range. gpiozero times the echo pulse in SOFTWARE on the Pi 5 (no pigpio), so a ping that
        # gets NO echo busy-waits the FULL timeout (proportional to max_distance), holding the GIL and starving
        # the wake-word mic. Cap it low (the FORWARD gate only cares about <30cm) to slash that wasted CPU.
        self.sensor_max_m = _envf("ROBOT_SENSOR_MAX_DISTANCE_M", 2.0)
        # --verbose (ROBOT_SENSOR_VERBOSE=1): stream a live SENSORS front/left/right read-out every
        # ROBOT_SENSOR_LOG_PERIOD_S seconds AND stop collapsing the gpiozero no-echo warning to one line,
        # so you can watch exactly what the ultrasonics are doing while it runs. Off by default (the sweep
        # actively reads all 3 beams, which adds a little load -- fine for a diagnosis run, not for "forever").
        self.sensor_verbose = os.environ.get("ROBOT_SENSOR_VERBOSE", "0") == "1"
        self.sensor_log_period = _envf("ROBOT_SENSOR_LOG_PERIOD_S", 2.0)
        # Resolve the board once via the HAL. Its default_pins() supply the PER-BOARD pin fallback below,
        # so core carries no board-specific pin constants: a Jetson gets its header pins, a Pi gets BCM.
        # An explicit env value (config/robot.env) still wins. hal.current() also applies the board's launch
        # env and is safe in dry-run (metadata only, no hardware); main.py already called it, so it's cached.
        import hal
        self._board = hal.current()
        # P2-7: pin resolution (env > board default_pins() > Pi hard default) lives in ONE place shared with
        # diagnostics.py, so the tool always probes the exact pins the robot drives.
        _p = hal.resolve_hcsr04_pins()
        trig, echo = _p["front"]
        left_trig, left_echo = _p["left"]
        right_trig, right_echo = _p["right"]

        # --- Failsafe: absolute cap on how long one command may keep the motor running ---
        self.max_move_ms = _envi("ROBOT_MAX_MOVE_MS", 5000)

        # --- PWM pulse-width ranges (us): used to drive the kit AND to compute the
        #     pulse width we log, so the console shows real microseconds either way. ---
        self._esc_pulse = (1000.0, 2000.0)     # continuous servo: -1..1 -> 1000..2000us (1500 neutral)
        self._steer_pulse = (500.0, 2500.0)    # servo: 0..180deg -> 500..2500us
        self._steer_actuation = 180.0

        # --- On-change log state (so the 20 Hz loop doesn't flood the console) ---
        self._log_throttle = None
        self._last_io_error = 0.0     # rate-limit state for the control-loop fault log (control thread only)
        self._log_steer = None
        self._gate_blocked = False
        self._gate_bad = 0            # consecutive FORWARD-gate close/failed reads (debounce vs sensor jitter)

        # --- Locks: _io serializes every I2C write; _lock guards shared state. ---
        self._io = threading.Lock()
        self._lock = threading.Lock()

        # --- Idle sensor quiescing (ROBOT_SENSOR_IDLE_QUIESCE, default on) ---
        # On the Pi 5 the ultrasonic echo is timed in SOFTWARE, so the 3 gpiozero DistanceSensor
        # background ping threads hog the GIL and starve the wake-word mic (-> OVERFLOW -> the wake word
        # goes sluggish/deaf after minutes). While IDLE (waiting for the wake word) we don't need obstacle
        # sensing at all, so main.py pause_sensing()'s them -- the threads stop and the mic runs clean.
        # A drive/explore resume_sensing()'s them (also auto-resumed by command() for any FORWARD/REVERSE).
        # gpiozero threads can't restart, so pause CLOSES the sensors and resume REBUILDS them.
        self.sensor_quiesce = os.environ.get("ROBOT_SENSOR_IDLE_QUIESCE", "1") == "1"
        self._sense_lock = threading.Lock()
        self._sensing_paused = False
        self._sensor_pins = {}           # {name: (trig, echo)} kept for the rebuild on resume (self._board set above)

        if self.dry_run:
            _mode = "DRY RUN -- no hardware will be driven"
        elif self.motors_off:
            _mode = ("MOTORS OFF (stationary) -- LIVE sensors/camera/voice/wake, but the ESC + steering "
                     "get NO PWM (wheels won't move; commands are still logged)")
        else:
            _mode = "LIVE HARDWARE"
        log.info("*** %s ***", _mode)
        log.info("PCA9685 I2C 0x40 (board=%s, bus=%s): ESC (Electronic Speed Controller) ch=%d, steer ch=%d | "
                 "FWD throttle %.2f..%.2f  REV %.2f..%.2f  invert=%d  neutral=%.2f(%.0fus)",
                 self._board.name, os.environ.get("ROBOT_I2C_BUS", "").strip() or "default",
                 self.esc_ch, self.steer_ch, self.fwd_floor, self.fwd_ceil,
                 self.rev_floor, self.rev_ceil, int(self.invert),
                 self.neutral, 1500.0 + self.neutral * 500.0)
        log.info("HC-SR04P x3 (%s pins): front TRIG=%d/ECHO=%d  left TRIG=%d/ECHO=%d  right TRIG=%d/ECHO=%d",
                 self._board.pin_scheme, trig, echo, left_trig, left_echo, right_trig, right_echo)
        log.info("obstacle gates: forward FORWARD-cut <%.0fcm | side steering-avoid <%.0fcm",
                 self.obstacle_cm, self.side_obstacle_cm)
        # Multi-board pin footgun: if the board uses BOARD (physical-header) numbering but the resolved pins
        # are exactly the Pi BCM defaults, the config almost certainly still has the Pi pins -- warn loudly
        # rather than silently drive the wrong header pins.
        if self._board.pin_scheme != "BCM" and \
                (trig, echo, left_trig, left_echo, right_trig, right_echo) == (23, 24, 5, 6, 20, 21):
            log.warning("SENSOR PINS are the Raspberry Pi BCM defaults (23/24/5/6/20/21) but board=%s uses %s "
                        "numbering -- set the board's header pins in config/robot.env (BOARD SELECT) or the "
                        "ultrasonics will read the WRONG pins.", self._board.name, self._board.pin_scheme)

        self.hw_failed = False   # set True below if a LIVE device init fails and we fall back to a fake
        if self.dry_run:
            self.kit = FakeServoKit(channels=channels)
            self._sensors = {
                "front": FakeDistanceSensor(cm=_envf("ROBOT_FAKE_DISTANCE_CM", 200.0)),
                "left": FakeDistanceSensor(cm=_envf("ROBOT_FAKE_LEFT_CM", 200.0)),
                "right": FakeDistanceSensor(cm=_envf("ROBOT_FAKE_RIGHT_CM", 200.0)),
            }
        else:
            # Real-hardware backends are built via the board HAL (brain/boards/<board>.py), not imported
            # here: on a laptop `import board` (pulled in by adafruit_servokit) raises NotImplementedError,
            # and on a Pi with no PCA9685 the ServoKit constructor raises -- the board's factory guards both.
            # Each device is built defensively: a hardware failure is LOGGED (naming the device and how to
            # fix it) and swapped for a fake, so the brain keeps running instead of crashing with a traceback.
            # (self._board was resolved above, before the pin defaults were read.)
            # gpiozero emits a DistanceSensorNoEcho warning on EVERY read with no echo -- ~15/sec with the
            # 3-sensor array unwired, which buries the real log. Collapse it to one line (Pi/gpiozero only; a
            # no-op where gpiozero isn't installed). The forward gate already fail-closes on a bad read.
            try:
                import warnings
                from gpiozero.exc import DistanceSensorNoEcho
                # --verbose wants to SEE every no-echo (that's the sensor telling you it's unwired / aimed at
                # open space); normal mode collapses it to one line so a genuine fault isn't buried.
                warnings.filterwarnings("default" if self.sensor_verbose else "once",
                                        category=DistanceSensorNoEcho)
            except Exception:
                pass

            # PCA9685 (ESC throttle + steering servo) -- built by the board; probes I2C 0x40, the usual
            # failure point.
            if self.motors_off:
                # STATIONARY mode: deliberately fake the PWM output so the ESC/servo get NO signal
                # (wheels won't move). Sensors below stay REAL. This is intentional, NOT hw_failed.
                log.info("*** MOTORS OFF (stationary): ESC/servo PWM is SIMULATED -- wheels will NOT move; "
                         "sensors, camera, face, voice + wake word are LIVE. ***")
                self.kit = FakeServoKit(channels=channels)
            else:
                try:
                    self.kit = self._board.make_pwm_kit(channels)
                except Exception as e:
                    log.error("HARDWARE FAILURE: PCA9685 not found on I2C 0x40: %s", e)
                    log.error("  fix: check the PCA9685 VCC/SDA/SCL/GND wiring + power and run `i2cdetect` on "
                              "the board's I2C bus (expect 0x40; Pi = bus 1, Jetson 40-pin header ~ bus 7 via "
                              "ROBOT_I2C_BUS). On the bench run with ROBOT_DRY_RUN=1. Motors are DISABLED.")
                    self.kit = FakeServoKit(channels=channels)
                    self.hw_failed = True

            # Three HC-SR04P distance sensors -- build each on its own (via the board) so one bad pin doesn't
            # take out the others (see _build_sensor_objs). Keep the pins so pause/resume_sensing() can
            # REBUILD them (gpiozero's ping threads can't be restarted, only recreated).
            self._sensor_pins = {
                "front": (trig, echo), "left": (left_trig, left_echo), "right": (right_trig, right_echo)}
            if self.sensor_type == "vl53l1x":
                self._tof_setup()   # ToF (I2C) path: prep the address/XSHUT plan before the first build
            self._sensors = self._build_sensor_objs()

            if self.hw_failed:
                log.error("*** RUNNING DEGRADED: some hardware is faked (see HARDWARE FAILURE above) -- "
                          "motion/sensing may be disabled, but the brain stays up. ***")
        self.sensor = self._sensors["front"]   # forward gate target + back-compat alias

        # ESC (Electronic Speed Controller) behaves like a continuous-rotation servo: throttle -1..1, 0 == neutral.
        self.kit.continuous_servo[self.esc_ch].set_pulse_width_range(
            int(self._esc_pulse[0]), int(self._esc_pulse[1]))
        self.kit.servo[self.steer_ch].set_pulse_width_range(
            int(self._steer_pulse[0]), int(self._steer_pulse[1]))
        self.kit.servo[self.steer_ch].actuation_range = int(self._steer_actuation)

        # --- Shared state (guarded by _lock) ---
        self._drive = "STOP"
        self._steer = "CENTER"
        self._throttle = 0.0          # target SIGNED throttle to write (fwd > neutral, rev < neutral)
        self._deadline = 0.0          # time.monotonic() after which we coast to neutral
        self._rev_prime_start = 0.0   # monotonic time the reverse double-tap began (0 = not priming)
        self._closed = False
        self.on_obstacle = None       # optional callback(distance_cm); dispatched on a daemon thread
                                      # (see _trip_obstacle) so its I/O can't stall the safety loop
        self._last_obstacle = 0.0

        self._arm()                   # ESC (Electronic Speed Controller) must see neutral before it will run (it will beep)
        with self._io:
            self._write_steer("CENTER")

        self._thread = threading.Thread(target=self._control_loop, daemon=True)
        self._thread.start()

        # --verbose: a low-rate background beam read-out so you can watch the sensors even while idle
        # (the control loop only reads the front beam while DRIVING, so without this you'd see nothing).
        if self.sensor_verbose:
            log.info("SENSOR VERBOSE: logging front/left/right every %.1fs -- and idle-quiescing is OFF "
                     "in verbose (sensors stay ON so you can watch them, so expect the wake mic to overflow; "
                     "run WITHOUT --verbose to see the quiescing fix).", self.sensor_log_period)
            threading.Thread(target=self._sensor_log_loop, daemon=True).start()

    # ---------- public API (mutate state only; the control thread drives the hardware) ----------
    def command(self, drive, steer, speed, duration_ms):
        """Replace the in-flight motion. A new command preempts the previous one."""
        drive = drive if drive in VALID_DRIVE else "STOP"
        steer = steer if steer in VALID_STEER else "CENTER"
        speed = max(0, min(100, int(speed)))
        duration_ms = max(0, min(self.max_move_ms, int(duration_ms)))
        # Defense-in-depth: a drive needs the obstacle gate, so make sure sensing is live even if the
        # caller forgot to resume_sensing() (the front gate reads -1 = fail-closed = won't move otherwise).
        if drive in ("FORWARD", "REVERSE") and self._sensing_paused:
            self.resume_sensing()
        throttle = self._speed_to_throttle(drive, speed) if drive != "STOP" else 0.0
        log.info("CMD drive=%s steer=%s speed=%d -> throttle=%.3f dur=%dms",
                 drive, steer, speed, throttle, duration_ms)
        with self._lock:
            now = time.monotonic()
            prev_drive, prev_deadline = self._drive, self._deadline
            self._drive = drive
            self._steer = steer
            self._throttle = throttle if drive != "STOP" else 0.0
            # Re-prime the double-tap on a FRESH reverse: either we weren't reversing, or the
            # previous reverse already expired (the ESC is back at neutral, so a new push would
            # only brake again). Keep priming state while an active reverse continues.
            extra = 0.0
            if drive == "REVERSE" and self.rev_doubletap and (
                    prev_drive != "REVERSE" or now > prev_deadline):
                self._rev_prime_start = now
                extra = (self.rev_brake_ms + self.rev_gap_ms) / 1000.0   # so reverse keeps its full duration
            elif drive != "REVERSE":
                self._rev_prime_start = 0.0
            self._deadline = now + extra + duration_ms / 1000.0

    def stop(self):
        with self._lock:
            self._drive = "STOP"
            self._throttle = 0.0
            self._deadline = 0.0
            self._rev_prime_start = 0.0   # next reverse re-primes the double-tap
        self._neutral()   # don't wait up to one loop tick to cut throttle

    def distance_cm(self, side="front"):
        if self._sensing_paused:
            return -1.0    # sensors quiesced while idle -> fail-closed (front gate blocks; sides read 'clear')
        sensor = self._sensors.get(side, self.sensor)
        try:
            cm = sensor.distance * 100.0
            # gpiozero can jitter a NEGATIVE distance under load (physically impossible) -- normalise any
            # such garbage to the -1.0 "read failed" sentinel so it's handled as a bad read, not an obstacle.
            return cm if cm >= 0.0 else -1.0
        except Exception:
            return -1.0

    def distances(self):
        """Snapshot of all three beams in cm (-1.0 if a read failed). For navigation/memory."""
        return {side: self.distance_cm(side) for side in ("front", "left", "right")}

    def side_blocked(self, steer):
        """True if steering LEFT/RIGHT points at a near wall (explore steering-avoid).
        A stale/failed read (-1.0) is treated as clear so a dead side sensor can't freeze steering."""
        side = {"LEFT": "left", "RIGHT": "right"}.get(steer)
        if side is None:
            return False
        d = self.distance_cm(side)
        return 0 <= d < self.side_obstacle_cm

    def close(self):
        with self._lock:
            self._closed = True
            self._drive = "STOP"      # so any in-flight control tick computes out=0, not a stale throttle
            self._throttle = 0.0
            self._rev_prime_start = 0.0
        if self._thread.is_alive():
            self._thread.join(timeout=1.0)
        self._neutral()
        with self._io:
            self._write_steer("CENTER")
        with self._sense_lock:
            self._sensing_paused = True   # latch: distance_cm fail-closes; resume must never rebuild post-close
            self._close_sensor_objs(list(self._sensors.values()))
        for x in (getattr(self, "_tof_xshut", None) or []):   # release VL53L1X XSHUT lines (ToF path only)
            try:
                x.close()
            except Exception:
                pass

    # ---------- idle sensor quiescing (see the ROBOT_SENSOR_IDLE_QUIESCE note in __init__) ----------
    def _tof_setup(self):
        """Prepare VL53L1X ToF state (ROBOT_SENSOR_TYPE=vl53l1x): the (name, XSHUT pin, I2C address) plan
        from the ROBOT_TOF_* keys. The I2C bus + one-time address assignment happen lazily in
        _build_tof_objs so a rebuild (resume_sensing) reuses the already-powered, already-addressed sensors."""
        def _addr(key, default):
            v = os.environ.get(key, "").strip()
            try:
                return int(v, 0) if v else default          # accepts 0x2A / 42
            except ValueError:
                return default
        self._tof_i2c = None
        self._tof_xshut = None
        self._tof_plan = [
            ("front", _envi("ROBOT_TOF_XSHUT_FRONT", 0), _addr("ROBOT_TOF_ADDR_FRONT", 0x2A)),
            ("left",  _envi("ROBOT_TOF_XSHUT_LEFT", 0),  _addr("ROBOT_TOF_ADDR_LEFT", 0x2B)),
            ("right", _envi("ROBOT_TOF_XSHUT_RIGHT", 0), _addr("ROBOT_TOF_ADDR_RIGHT", 0x29)),
        ]

    def _build_tof_objs(self, quiet=False):
        """Build the 3 VL53L1X ToF sensors (ROBOT_SENSOR_TYPE=vl53l1x). Addresses are assigned ONCE (first
        build); rebuilds (resume_sensing) reuse the powered/addressed sensors -- the XSHUT handles are kept
        on self._tof_xshut so the sensors stay up across a pause. A failure falls back to a fake that reads
        'clear' for that beam, exactly like the HC-SR04 path, so one bad sensor never stalls the safety loop."""
        import vl53l1x_sensor as tof
        try:
            if self._tof_i2c is None:
                self._tof_i2c = tof.make_i2c()
            if self._tof_xshut is None:                     # first build -> assign addresses from 0x29 once
                plan = [(pin, addr) for (_n, pin, addr) in self._tof_plan]
                self._tof_xshut = tof.assign_addresses(self._tof_i2c, plan, self._board.make_digital_output)
        except Exception as e:
            (log.debug if quiet else log.error)(
                "HARDWARE FAILURE: VL53L1X setup failed: %s -> all ToF beams faked (obstacle gates DISABLED). "
                "Check I2C wiring/bus (ROBOT_I2C_BUS) + the ROBOT_TOF_XSHUT_* pins.", e)
            self.hw_failed = True
            return {name: FakeDistanceSensor(cm=400.0) for (name, _p, _a) in self._tof_plan}
        sensors = {}
        for name, _pin, addr in self._tof_plan:
            try:
                sensors[name] = tof.VL53L1XSensor(self._tof_i2c, addr, self.sensor_max_m)
            except Exception as e:
                (log.debug if quiet else log.error)(
                    "HARDWARE FAILURE: VL53L1X %s @0x%02x init failed: %s -> faked; its obstacle gate is "
                    "DISABLED.", name, addr, e)
                sensors[name] = FakeDistanceSensor(cm=400.0)
                self.hw_failed = True
        return sensors

    def _build_sensor_objs(self, quiet=False):
        """Build the 3 distance sensors. ROBOT_SENSOR_TYPE selects the backend: 'vl53l1x' -> I2C ToF
        (_build_tof_objs); 'hcsr04' (default) -> the HC-SR04 path below, built from self._sensor_pins via the
        board HAL (gpiozero's DistanceSensor on the Pi). Each on its own so one bad pin doesn't take out the
        others; a failure falls back to a fake (reads 'clear'). `quiet` softens the per-sensor failure log to
        DEBUG for rebuilds (resume_sensing) so a turn-by-turn rebuild of an unwired sensor doesn't spam ERROR."""
        if getattr(self, "sensor_type", "hcsr04") == "vl53l1x":
            return self._build_tof_objs(quiet=quiet)
        sensors = {}
        for name, (t_pin, e_pin) in self._sensor_pins.items():
            try:
                # The board's factory owns the driver specifics (on the Pi, gpiozero with partial=True so a
                # dead/unwired sensor can never block the 20 Hz safety loop).
                sensors[name] = self._board.make_distance_sensor(t_pin, e_pin, self.sensor_max_m)
            except Exception as e:
                (log.debug if quiet else log.error)(
                    "HARDWARE FAILURE: %s HC-SR04P (TRIG GPIO%d / ECHO GPIO%d) init failed: %s "
                    "-> faked; its obstacle gate is DISABLED.", name, t_pin, e_pin, e)
                sensors[name] = FakeDistanceSensor(cm=400.0)
                self.hw_failed = True
        return sensors

    @staticmethod
    def _close_sensor_objs(sensors):
        for sensor in sensors:
            # gpiozero races its own close(): the background "fill" thread can still be mid-read when
            # close() tears the trigger pin down -> AttributeError tracebacks. Stop that thread FIRST
            # (internal but stable attr; the dry-run fakes simply lack it).
            try:
                q = getattr(sensor, "_queue", None)
                if q is not None:
                    q.stop()
            except Exception:
                pass
            try:
                sensor.close()
            except Exception:
                pass

    def pause_sensing(self):
        """Quiesce the ultrasonics while IDLE (waiting for the wake word): CLOSE the 3 gpiozero sensors so
        their software-timed ping threads stop hogging the GIL + starving the wake mic. Rebuilt on the next
        drive/explore. Idempotent. No-op in dry-run, when quiescing is off, or in --verbose (there you WANT
        to keep watching the sensors)."""
        if self.dry_run or not self.sensor_quiesce or self.sensor_verbose:
            return
        with self._lock:
            wait_s = self._deadline - time.monotonic()
            move_in_flight = self._drive in ("FORWARD", "REVERSE") and wait_s > 0
        if move_in_flight:
            # Pausing NOW would make the FORWARD gate read -1 (fail-closed) and falsely trip the obstacle
            # stop mid-move. Re-try the quiesce just after the move's deadline instead. pause_sensing
            # re-checks state on re-entry: a newer command defers again, and a resume_sensing() in
            # between is respected. Idempotent, so stacked timers are harmless.
            log.info("sensing pause deferred %.1fs: a timed move is still in flight", wait_s)
            t = threading.Timer(wait_s + 0.2, self.pause_sensing)
            t.daemon = True
            t.start()
            return
        with self._sense_lock:
            if self._sensing_paused:
                return
            self._sensing_paused = True   # set FIRST: distance_cm short-circuits before touching a closing sensor
            self._close_sensor_objs(list(self._sensors.values()))
        log.info("sensing PAUSED (idle) -- ultrasonic threads stopped to free the wake-word mic")

    def resume_sensing(self):
        """Rebuild the ultrasonics after a pause (before a drive/explore reads them). Idempotent; no-op in
        dry-run / quiescing-off / --verbose (they were never paused there)."""
        if self.dry_run or not self.sensor_quiesce or self.sensor_verbose:
            return
        with self._sense_lock:
            if self._closed:
                return   # shutting down -- never rebuild sensors after close()
            if not self._sensing_paused:
                return
            self._sensors = self._build_sensor_objs(quiet=True)   # fresh objects/threads
            self.sensor = self._sensors.get("front", self.sensor)
            self._sensing_paused = False   # clear LAST: reads see the new sensors, never a half-built dict
        log.info("sensing RESUMED -- ultrasonic sensors rebuilt for this drive/turn")

    # ---------- internals ----------
    def _arm(self):
        # Holding neutral is what arms the ESC. For an offset ESC, ROBOT_ESC_NEUTRAL (e.g. 0.25) is that
        # rest value -- holding it arms + keeps the wheels still. Keep the ESC powered at brain start.
        self._neutral()
        time.sleep(self.arm_secs)

    def _neutral(self):
        with self._io:
            try:
                self._write_throttle(self.neutral)
            except Exception as e:
                # CRIT-01: a FAILED emergency-neutral write must NOT be silently swallowed. Invalidate the
                # write cache so the next control-loop tick is forced to retry, and log it LOUD -- otherwise
                # the ESC can keep driving with no trace.
                self._log_throttle = None
                log.error("NEUTRAL write FAILED (ESC may still be driving!): %s -- will retry each tick", e)

    def _speed_to_throttle(self, drive, speed):
        """Map a 0..100 speed onto the ESC's usable band for `drive`, returning the ACTUAL SIGNED throttle
        to write (NOT a magnitude): FORWARD sits ABOVE the (possibly offset) neutral, REVERSE BELOW it.
        MIN_*_SPEED (floor) = the slowest end (just engages), MAX_*_SPEED (ceil) = fastest. Reverse's max is
        deeper below neutral than its min -- e.g. neutral 0.25, MIN_REVERSE 0.00 (1500us crawl), MAX_REVERSE
        -0.20 (1400us, faster). speed 0 -> neutral (no motion). ROBOT_SPEED_INCREMENT_STEP quantizes it."""
        if speed <= 0:
            return self.neutral
        s = max(0.0, min(1.0, speed / 100.0))
        floor, ceil = ((self.rev_floor, self.rev_ceil) if drive == "REVERSE"
                       else (self.fwd_floor, self.fwd_ceil))
        floor = max(-1.0, min(1.0, floor))
        ceil = max(-1.0, min(1.0, ceil))
        raw = floor + s * (ceil - floor)
        step = self.speed_step
        if step and step > 0:
            raw = floor + round((raw - floor) / step) * step   # quantize to ROBOT_SPEED_INCREMENT_STEP from floor
            lo, hi = (floor, ceil) if floor <= ceil else (ceil, floor)
            raw = max(lo, min(hi, raw))                         # keep it inside the band after rounding
        return raw

    def _esc_pulse_us(self, value):
        lo, hi = self._esc_pulse
        return (lo + hi) / 2.0 + value * (hi - lo) / 2.0

    def _steer_pulse_us(self, angle):
        lo, hi = self._steer_pulse
        return lo + (angle / self._steer_actuation) * (hi - lo)

    def _write_throttle(self, value):    # caller MUST hold self._io
        if self.invert:
            # Mirror around neutral: swaps FWD/REV but keeps the fixed STOP/neutral pulse.
            # For the default neutral=0.0 this reduces to -value (unchanged).
            value = 2.0 * self.neutral - value
        value = max(-1.0, min(1.0, value))
        rv = round(value, 3)
        # WRITE-ON-CHANGE: only push to the PCA9685 when the value actually changes. Re-writing the same
        # neutral 20x/sec can disturb the dead-steady signal a cheap ESC needs to arm; once written, the
        # PCA9685 holds the pulse in hardware. A STOP/obstacle still changes the value -> still writes.
        if rv == self._log_throttle:
            return
        log.info("I2C->PCA9685 ESC (Electronic Speed Controller)   ch=%d throttle=%+.3f pulse_us=%.0f",
                 self.esc_ch, value, self._esc_pulse_us(value))
        self.kit.continuous_servo[self.esc_ch].throttle = value
        self._log_throttle = rv    # CRIT-01: cache ONLY after the write succeeds -- a raised I2C write must
                                   # leave the cache stale so the next tick retries (else a poisoned cache
                                   # skips every retry and the ESC keeps its last pulse -> can't neutralise)

    def _write_steer(self, steer):       # caller MUST hold self._io
        angle = {"LEFT": self.steer_left, "RIGHT": self.steer_right}.get(steer, self.steer_center)
        angle = max(0.0, min(180.0, angle))
        if steer == self._log_steer:     # write-on-change (same reasoning as _write_throttle)
            return
        log.info("I2C->PCA9685 SERVO ch=%d steer=%-6s angle=%.1fdeg pulse_us=%.0f",
                 self.steer_ch, steer, angle, self._steer_pulse_us(angle))
        self.kit.servo[self.steer_ch].angle = angle
        self._log_steer = steer          # CRIT-01: cache only after the write succeeds (see _write_throttle)

    def _control_loop(self):
        # Runs at ~20 Hz. This loop is the failsafe AND the sole normal-operation writer of
        # the PWM outputs: it always converges to neutral unless a fresh, unexpired
        # FORWARD/REVERSE command says otherwise.
        while True:
            # NOTHING may escape this loop -- it is the sole failsafe thread AND the sole PWM writer.
            # The ENTIRE body is wrapped (Step 6): a fault in the snapshot / gate / _trip_obstacle spawn
            # must force neutral and keep ticking, not kill the thread. `break` stays inside (exception-
            # free); time.sleep(0.05) stays OUTSIDE so a persistent fault ticks at ~20 Hz, not busy-spins.
            try:
                with self._lock:
                    if self._closed:
                        break
                    drive, throttle, steer, deadline = (
                        self._drive, self._throttle, self._steer, self._deadline)
                    rev_prime_start = self._rev_prime_start

                out = self.neutral
                if drive in ("FORWARD", "REVERSE") and time.monotonic() <= deadline:
                    if drive == "FORWARD":
                        d = self.distance_cm()
                        # Fail CLOSED: too close OR a failed read (-1.0) HOLDS neutral immediately. But only
                        # ABORT the move once the bad condition PERSISTS (obstacle_debounce frames) -- gpiozero's
                        # software timing jitters an odd garbage frame under load, and one such frame must not
                        # kill a drive. We never drive while unsure (out stays neutral on any bad read). A
                        # dead/silent sensor that saturates at max range still reads "clear" -- not
                        # distinguishable in software from a genuinely open path; documented as a limitation.
                        if d < self.obstacle_cm:
                            out = self.neutral
                            self._gate_bad += 1
                            if self._gate_bad >= self.obstacle_debounce:
                                if not self._gate_blocked:
                                    self._gate_blocked = True
                                    log.info("GATE FORWARD blocked: front=%.1fcm (need >= %.1fcm; <0 = read error) "
                                             "after %d frames", d, self.obstacle_cm, self._gate_bad)
                                self._trip_obstacle(d)   # confirmed -> state STOP + fires callback
                        else:
                            self._gate_bad = 0
                            self._gate_blocked = False
                            out = throttle
                    else:
                        # REVERSE is UNSENSED (no rear sensor) -- bounded only by the move deadline + throttle
                        # cap. `throttle` is already the SIGNED reverse value (below neutral); write it directly.
                        out = throttle
                        if rev_prime_start:
                            # Double-tap an F/B/R ESC: tap1 (brake) -> neutral gap -> sustained reverse.
                            el_ms = (time.monotonic() - rev_prime_start) * 1000.0
                            if self.rev_brake_ms <= el_ms < self.rev_brake_ms + self.rev_gap_ms:
                                out = self.neutral  # neutral gap between the two taps
                            # el < brake_ms: tap1 (reverse pulse = brake on F/B/R); past the gap: real reverse

                with self._io:
                    # Re-validate under _lock right before the write: a STOP / close / obstacle-trip
                    # that landed in the gap since the snapshot above MUST win, so an emergency stop
                    # can never be overwritten by a stale throttle for one tick. (We take _io then
                    # _lock; no other path holds _lock while acquiring _io, so there's no deadlock.)
                    with self._lock:
                        if self._closed or self._drive == "STOP":
                            out = self.neutral
                    self._write_throttle(out)
                    self._write_steer(steer)
            except Exception as e:
                # _io/_lock were released as the exception propagated out of their `with` blocks, so
                # _neutral() (itself guarded, and it invalidates the write cache on failure) can safely
                # re-acquire _io. Log rate-limited (Step 16) so a degrading I2C link is visible without
                # flooding at 20 Hz.
                self._neutral()
                now = time.monotonic()
                if now - self._last_io_error > 1.0:
                    self._last_io_error = now
                    log.error("control loop fault (forced neutral, will retry): %s: %s",
                              type(e).__name__, e)
            time.sleep(0.05)

        self._neutral()

    def _trip_obstacle(self, distance_cm):
        with self._lock:
            self._drive = "STOP"
            self._throttle = 0.0
        now = time.monotonic()
        cb = self.on_obstacle
        if cb and now - self._last_obstacle > 3.0:   # debounce
            self._last_obstacle = now
            # Fire the callback on a daemon thread, NOT inline. _trip_obstacle runs on the 20 Hz
            # safety control thread, and runs BEFORE this tick's throttle-cut write. on_obstacle does
            # I/O (a SQLite write with an fsync, an earcon/TTS spawn) -- a slow SD-card fsync inline
            # here would BOTH stall the safety loop AND delay the physical motor stop. Off-thread keeps
            # the throttle cut immediate no matter what the callback does.
            try:
                threading.Thread(target=self._safe_cb, args=(cb, distance_cm), daemon=True).start()
            except Exception:
                pass   # thread/FD exhaustion must not kill the failsafe thread; state is already STOP

    @staticmethod
    def _safe_cb(cb, distance_cm):
        try:
            cb(distance_cm)
        except Exception:
            pass

    def _sensor_log_loop(self):
        """--verbose only: log all three beams periodically so the operator can watch the ultrasonics
        live. '--' = no echo / read error (-1). Runs on its own daemon thread; exits when the driver closes."""
        period = max(0.5, self.sensor_log_period)
        while True:
            with self._lock:
                if self._closed:
                    break
            d = self.distances()
            def _fmt(v):
                return f"{v:.0f}cm" if v >= 0 else "--"
            log.info("SENSORS  front=%-6s left=%-6s right=%-6s  (gate<%.0f | side<%.0f)",
                     _fmt(d["front"]), _fmt(d["left"]), _fmt(d["right"]),
                     self.obstacle_cm, self.side_obstacle_cm)
            time.sleep(period)
